// 更可靠的行動裝置偵測（含 iPadOS）- 與 cameraManager 保持一致
function isMobileLike() {
  const ua = (navigator.userAgent || "").toLowerCase();
  const uaDataMobile = navigator.userAgentData?.mobile === true;
  const touchMac = navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1; // iPadOS 假裝 Mac
  const classicMobile = /iphone|ipad|ipod|android/.test(ua);
  return uaDataMobile || touchMac || classicMobile;
}

function detectDesktop() {
  return !isMobileLike();
}

/** 依 contentFrame 寬度在 bgCanvas 補左右黑邊（桌機專用） */
function drawPillarBars(ctx, canvasW, canvasH) {
  try {
    // 優先用實際容器寬（CSS 像素）
    let contentCssW = 0;
    if (contentFrameEl) {
      const rect = contentFrameEl.getBoundingClientRect();
      contentCssW = Math.round(rect.width);
    }
    // 備援：用 480 當 content 最大寬
    if (!contentCssW) {
      const maxPx = 480;
      contentCssW = Math.min(lastCssW || window.innerWidth || maxPx, maxPx);
    }

    // 將 CSS 寬換算成 canvas 像素寬
    const scaleX = canvasW / (lastCssW || canvasW);
    const contentCanvasW = Math.round(contentCssW * scaleX);

    const side = Math.max(0, Math.floor((canvasW - contentCanvasW) / 2));
    if (side > 0) {
      ctx.save();
      ctx.fillStyle = "#000";
      ctx.fillRect(0, 0, side, canvasH); // 左黑邊
      ctx.fillRect(canvasW - side, 0, side, canvasH); // 右黑邊
      ctx.restore();
    }
  } catch {}
}

