// -----------------------------------------------------------------------------
// 畫布尺寸同步
// -----------------------------------------------------------------------------
export function syncCanvasSize() {
  const stageEl = outCanvas.closest(".stage") || outCanvas.parentElement;

  // 1) 取可視區尺寸（行動裝置地址列收合更準）
  const getViewportSize = () => {
    const vv = window.visualViewport;
    return {
      w: Math.round(
        vv?.width ||
          window.innerWidth ||
          document.documentElement.clientWidth ||
          360
      ),
      h: Math.round(
        vv?.height ||
          window.innerHeight ||
          document.documentElement.clientHeight ||
          640
      ),
    };
  };

  // 2) CSS 尺寸（邏輯像素）：滿版就直接吃 viewport；否則吃容器 rect
  let cssW, cssH;
  if (CONFIG.DISPLAY?.FULLBLEED) {
    const { w, h } = getViewportSize();
    cssW = w;
    cssH = h;

    if (stageEl && stageEl.style) {
      stageEl.style.position = "fixed";
      stageEl.style.top = "0";
      stageEl.style.left = "0";
      stageEl.style.right = "0";
      stageEl.style.bottom = "0";
      stageEl.style.width = "100dvw";
      stageEl.style.height = "100dvh";
      stageEl.style.margin = "0";
      stageEl.style.padding = "0";
      stageEl.style.overflow = "hidden";
    }
  } else {
    const rect = stageEl.getBoundingClientRect();
    cssW = Math.max(320, Math.round(rect.width));
    cssH = Math.max(240, Math.round(rect.height));
  }

  // 記住 CSS 尺寸（給 pillarbox 換算用）
  lastCssW = cssW;
  lastCssH = cssH;

  // 3) 像素層級的軟上限：限制「有效 DPR」而非 CSS 尺寸
  const dpr = Math.max(1, Math.min(window.devicePixelRatio || 1, 3));
  const maxWpx = window.innerWidth > 768 ? 1920 : 1280;
  const maxHpx = window.innerHeight > 1024 ? 1080 : 1280;

  const dprEff = Math.min(dpr, maxWpx / cssW, maxHpx / cssH);

  const pixelW = Math.round(cssW * dprEff);
  const pixelH = Math.round(cssH * dprEff);

  const setSize = (c) => {
    if (c.width !== pixelW || c.height !== pixelH) {
      c.width = pixelW; // 實際像素（決定清晰度）
      c.height = pixelH;
    }
    c.style.width = `${cssW}px`; // CSS 尺寸（決定畫面是否滿版）
    c.style.height = `${cssH}px`;
  };

  [bgCanvas, maskCanvas, outCanvas, videoDrawCanvas, compositeCanvas].forEach(
    setSize
  );

  lastMaskSize = { w: outCanvas.width, h: outCanvas.height };
}

// -----------------------------------------------------------------------------
// 背景繪製（含「影片」背景選項）
// -----------------------------------------------------------------------------
function renderBackgroundTo(ctx, w, h) {
  const bgType =
    (CONFIG.BACKGROUND && CONFIG.BACKGROUND.TYPE) ||
    (CONFIG.BACKGROUND_EFFECTS &&
      CONFIG.BACKGROUND_EFFECTS.DEFAULT_BACKGROUND) ||
    "original";
  const intensity =
    CONFIG.BACKGROUND && typeof CONFIG.BACKGROUND.INTENSITY === "number"
      ? CONFIG.BACKGROUND.INTENSITY
      : (CONFIG.BACKGROUND_EFFECTS &&
          CONFIG.BACKGROUND_EFFECTS.EFFECT_INTENSITY) ??
        0.5;

  ctx.clearRect(0, 0, w, h);
  animT += 0.016;

  if (bgType === "original") {
    // 透明
    return;
  }
  if (bgType === "waves") {
    const grad = ctx.createLinearGradient(0, 0, w, h);
    grad.addColorStop(0, "#1a2332");
    grad.addColorStop(0.5, "#2d3a50");
    grad.addColorStop(1, "#0f1419");
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = `rgba(100,200,255,${intensity * 0.6})`;
    ctx.lineWidth = 2;
    for (let i = 0; i < 8; i++) {
      ctx.beginPath();
      for (let x = 0; x < w; x += 5) {
        const off = i * 50;
        const y =
          h / 2 + Math.sin((x + off) * 0.012 + animT * 1.2) * 20 * intensity;
        if (x === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.stroke();
    }
    return;
  }
  if (bgType === "frequency") {
    ctx.fillStyle = "#0a0a0a";
    ctx.fillRect(0, 0, w, h);
    const bands = 48;
    const bw = w / bands;
    for (let i = 0; i < bands; i++) {
      const x = i * bw;
      const bh =
        (Math.sin(animT * 2 + i * 0.2) * 0.5 + 0.5) * h * 0.5 * intensity;
      const hue = (animT * 30 + i * 10) % 360;
      ctx.fillStyle = `hsla(${hue},70%,60%,0.8)`;
      ctx.fillRect(x, h - bh, bw - 1, bh);
    }
    return;
  }
  if (bgType === "video" && bgVideoEl) {
    // 以 cover 方式鋪滿
    const vw = bgVideoEl.videoWidth || 1;
    const vh = bgVideoEl.videoHeight || 1;
    if (bgVideoEl.readyState >= 2) {
      const scale = Math.max(w / vw, h / vh);
      const dw = Math.round(vw * scale);
      const dh = Math.round(vh * scale);
      const ox = Math.round((w - dw) / 2);
      const oy = Math.round((h - dh) / 2);
      try {
        if (bgVideoEl.paused) bgVideoEl.play().catch(() => {});
      } catch {}
      ctx.globalAlpha = Math.min(1, 0.3 + intensity * 0.7);
      ctx.drawImage(bgVideoEl, 0, 0, vw, vh, ox, oy, dw, dh);
      ctx.globalAlpha = 1;
    }
    return;
  }

  // 月相影片背景（略：維持你原本流程）
  if (bgType === "moon_video" && bgMoonVideoEl) {
    try {
      if (bgMoonVideoEl.readyState >= 2 && !bgMoonVideoEl.paused) {
        const vw = bgMoonVideoEl.videoWidth || bgMoonVideoEl.width || 1;
        const vh = bgMoonVideoEl.videoHeight || bgMoonVideoEl.height || 1;
        if (vw > 1 && vh > 1) {
          const scale = Math.max(w / vw, h / vh);
          const dw = Math.round(vw * scale);
          const dh = Math.round(vh * scale);
          const ox = Math.round((w - dw) / 2);
          const oy = Math.round((h - dh) / 2);
          ctx.globalAlpha = Math.min(1, 0.3 + intensity * 0.7);
          ctx.drawImage(bgMoonVideoEl, 0, 0, vw, vh, ox, oy, dw, dh);
          ctx.globalAlpha = 1;
        }
      } else if (bgMoonVideoEl && bgMoonVideoEl.paused) {
        bgMoonVideoEl.play().catch((e) => console.warn("月相影片播放失敗:", e));
      }
    } catch (e) {
      console.warn("月相影片渲染錯誤:", e);
    }
    return;
  }

  // custom_moon_bg 分支（略）：維持你原本流程
}

