// -----------------------------------------------------------------------------
// 蒙版處理（EMA 平滑 + 邊緣羽化）
// -----------------------------------------------------------------------------
function emaUpdate(srcF32, w, h) {
  const N = w * h;
  if (!lastMaskF32 || lastMaskSize.w !== w || lastMaskSize.h !== h) {
    lastMaskF32 = new Float32Array(N);
    lastMaskF32.set(srcF32);
    lastMaskSize = { w, h };
    return lastMaskF32;
  }
  const a = CONFIG.SMOOTHING.TEMPORAL_ALPHA;
  for (let i = 0; i < N; i++) {
    lastMaskF32[i] = a * lastMaskF32[i] + (1 - a) * srcF32[i];
  }
  return lastMaskF32;
}

function buildAlphaImage(maskF32, w, h) {
  const T = CONFIG.SMOOTHING.THRESHOLD;
  const N = w * h;
  const img = new ImageData(w, h);
  for (let i = 0, j = 0; i < N; i++, j += 4) {
    const v = maskF32[i];
    const a = v >= T ? Math.min(255, Math.round(v * 255)) : 0;
    img.data[j] = 0;
    img.data[j + 1] = 0;
    img.data[j + 2] = 0;
    img.data[j + 3] = a;
  }
  maskBaseCanvas.width = w;
  maskBaseCanvas.height = h;
  maskBaseCtx.putImageData(img, 0, 0);

  const VW = outCanvas.width,
    VH = outCanvas.height;
  maskUpscaleCanvas.width = VW;
  maskUpscaleCanvas.height = VH;
  maskUpscaleCtx.clearRect(0, 0, VW, VH);
  maskUpscaleCtx.imageSmoothingEnabled = true;
  maskUpscaleCtx.imageSmoothingQuality = "high";
  maskUpscaleCtx.drawImage(maskBaseCanvas, 0, 0, VW, VH);

  const blurPx = CONFIG.SMOOTHING.EDGE_FEATHER_PX;
  maskSoftCanvas.width = VW;
  maskSoftCanvas.height = VH;
  maskSoftCtx.clearRect(0, 0, VW, VH);
  maskSoftCtx.filter = blurPx > 0 ? `blur(${blurPx}px)` : "none";
  maskSoftCtx.drawImage(maskUpscaleCanvas, 0, 0);
  maskSoftCtx.filter = "none";
  return maskSoftCanvas;
}

// -----------------------------------------------------------------------------
// 臉部檢測 / 區域與疊圖
// -----------------------------------------------------------------------------
function checkFacesInArea(detections) {
  return detections; // 目前整畫面
}

function renderOverlay(detections) {
  const W = outCanvas.width,
    H = outCanvas.height;
  outCtx.save();
  outCtx.translate(W, 0);
  outCtx.scale(-1, 1);

  const facesIn = checkFacesInArea(detections);
  outCtx.restore();

  if (detections.length > 0) {
    dlog(
      "🔍 偵測到",
      detections.length,
      "個人臉，符合條件的:",
      facesIn.length
    );
  }

  const wantActive = facesIn.length >= CONFIG.FACE_DETECTION_SETTINGS.REQUIRED_FACES;

  // 遲滯 + 去彈跳
  if (wantActive) {
    _enterCount++;
    _exitCount = 0;
  } else {
    _exitCount++;
    _enterCount = 0;
  }

  let newState = _effectActive;
  if (!_effectActive && _enterCount >= ENTER_CONSEC_FRAMES) newState = true;
  if (_effectActive && _exitCount >= EXIT_CONSEC_FRAMES) newState = false;

  if (newState !== _effectActive) {
    const now = performance.now();
    if (now - _lastTriggerAt > TRIGGER_COOLDOWN_MS) {
      _lastTriggerAt = now;
      _effectActive = newState;
      if (_effectActive) onStatus?.("TRIGGER_TEST_EFFECT");
      else onStatus?.("STOP_TEST_EFFECT");
    }
  }

  onStats({
    faceCount: detections.length,
    facesInArea: facesIn.length,
    effectActive: _effectActive,
  });
}

// -----------------------------------------------------------------------------
// 主渲染迴圈
// -----------------------------------------------------------------------------
async function renderLoop() {
  if (!running) return;
  const now = performance.now();
  const W = outCanvas.width,
    H = outCanvas.height;

  // 1) 先把相機畫面投到 videoDrawCanvas（cover + 置中）
  videoDrawCtx.clearRect(0, 0, W, H);
  const vw = videoEl.videoWidth || 1,
    vh = videoEl.videoHeight || 1;
  const scale = Math.max(W / vw, H / vh);
  const dw = Math.round(vw * scale),
    dh = Math.round(vh * scale);
  const ox = Math.round((W - dw) / 2),
    oy = Math.round((H - dh) / 2);
  try {
    videoDrawCtx.drawImage(videoEl, 0, 0, vw, vh, ox, oy, dw, dh);
  } catch {}

  // 1.5) 建立較小的處理用畫布（避免把整個螢幕原解析度丟進 AI）
  const targetW = Math.min(640, Math.floor(W)); // 上限 640
  const targetH = Math.round(targetW * (H / W)); // 依當前畫面 AR
  if (procCanvas.width !== targetW || procCanvas.height !== targetH) {
    procCanvas.width = targetW;
    procCanvas.height = targetH;
  }
  procCtx.clearRect(0, 0, targetW, targetH);
  procCtx.drawImage(videoDrawCanvas, 0, 0, targetW, targetH);

  // 2) 接著決定「底層」要畫什麼
  bgCtx.clearRect(0, 0, W, H);
  if (CONFIG.BACKGROUND?.TYPE === "person_overlay") {
    // 底層以相機畫面為主，根据镜头模式决定是否镜像
    bgCtx.save();
    if (currentFacingMode === "user") {
      // 前镜头：背景层镜像（因为outputCanvas会被CSS镜像，需要预镜像以抵消）
      bgCtx.translate(W, 0);
      bgCtx.scale(-1, 1);
    }
    // 后镜头：不镜像背景层
    bgCtx.drawImage(videoDrawCanvas, 0, 0, W, H);
    bgCtx.restore();

    // 只有桌機才補 pillarbox（左右黑邊）
    if (isDesktopDevice) {
      drawPillarBars(bgCtx, W, H);
    }
  } else {
    // 其他背景型別走原本流程（特效 / 月亮 / 影片等）
    renderBackground(W, H);
  }

  // 3) 清空頂層，準備人像覆蓋
  outCtx.clearRect(0, 0, W, H);

  // 4) 分割（節流 + 降採樣）
  if (CONFIG.SEGMENTATION.ENABLED) {
    if (videoEl.currentTime !== lastVideoTime) {
      const nowMs = performance.now();
      if (nowMs - _lastSegAt >= SEG_INTERVAL_MS) {
        _lastSegAt = nowMs;
        lastVideoTime = videoEl.currentTime;
        // 确保 MediaPipe 时间戳单调递增
        const timestamp = Math.max(nowMs, lastTimestamp + 1);
        lastTimestamp = timestamp;
        const result = await mediaPipeManager.segmentImage(
          procCanvas,
          timestamp
        );
        if (result) {
          let maskF32 = null,
            mw = 0,
            mh = 0;
          if (result.confidenceMasks && result.confidenceMasks.length) {
            const idx =
              personLabelIndex < result.confidenceMasks.length
                ? personLabelIndex
                : 0;
            const cm = result.confidenceMasks[idx];
            if (cm?.getAsFloat32Array) {
              const src = cm.getAsFloat32Array();
              maskF32 = new Float32Array(src.length);
              maskF32.set(src);
              mw = cm.width;
              mh = cm.height;
            }
            for (const m of result.confidenceMasks) {
              try {
                m?.close?.();
              } catch {}
            }
          } else if (result.categoryMask?.getAsUint8Array) {
            const cat = result.categoryMask;
            const u8 = cat.getAsUint8Array();
            maskF32 = new Float32Array(u8.length);
            mw = cat.width;
            mh = cat.height;
            const personIdx = personLabelIndex;
            for (let i = 0; i < u8.length; i++)
              maskF32[i] = u8[i] === personIdx ? 1 : 0;
            try {
              cat.close?.();
            } catch {}
          }
          if (maskF32 && mw && mh) {
            const sm = emaUpdate(maskF32, mw, mh);
            gMaskCanvasProcessed = buildAlphaImage(sm, mw, mh);
          }
        }
      }
    }
  } else {
    gMaskCanvasProcessed = null;
  }

  // 5) 先把人物合成到離屏（避免破壞底層）
  compositeCtx.clearRect(0, 0, W, H);
  compositeCtx.save();
  compositeCtx.drawImage(videoDrawCanvas, 0, 0, W, H);
  if (gMaskCanvasProcessed) {
    compositeCtx.globalCompositeOperation = "destination-in";
    compositeCtx.drawImage(gMaskCanvasProcessed, 0, 0, W, H);
    compositeCtx.globalCompositeOperation = "source-over";
  }
  compositeCtx.restore();

  // 6) 輸出：person_overlay 僅畫人像；其他模式畫整張 composite
  if (CONFIG.BACKGROUND?.TYPE === "person_overlay") {
    if (gMaskCanvasProcessed && CONFIG.SEGMENTATION.ENABLED) {
      // 不使用绘制镜像，让CSS镜像负责最终显示
      outCtx.drawImage(videoDrawCanvas, 0, 0, W, H);
      outCtx.globalCompositeOperation = "destination-in";
      outCtx.drawImage(gMaskCanvasProcessed, 0, 0, W, H);
      outCtx.globalCompositeOperation = "source-over";
    }
  } else {
    // 不使用绘制镜像，让CSS镜像负责最终显示
    outCtx.drawImage(compositeCanvas, 0, 0, W, H);
  }

  // 7) Mask 預覽
  maskCtx.clearRect(0, 0, W, H);
  if (gMaskCanvasProcessed && _showMaskPreview) {
    maskCtx.globalAlpha = 0.9;
    maskCtx.drawImage(gMaskCanvasProcessed, 0, 0, W, H);
    maskCtx.globalAlpha = 1.0;
    maskCanvas.style.display = "block";
  } else {
    maskCanvas.style.display = "none";
  }

  // 8) 臉部檢測（節流 + 降採樣）
  {
    const nowMs = performance.now();
    if (nowMs - _lastFaceDetAt >= FACE_DET_INTERVAL_MS) {
      _lastFaceDetAt = nowMs;
      const timestamp = Math.max(nowMs, lastTimestamp + 1);
      lastTimestamp = timestamp;
      const det = mediaPipeManager.detectFaces(procCanvas, timestamp);
      if (det) renderOverlay(det.detections || []);
      else renderOverlay([]);
    }
  }

  requestAnimationFrame(renderLoop);
}

// -----------------------------------------------------------------------------
// 公開 API：start/stop/onResize & 參數 setters
// -----------------------------------------------------------------------------
export async function start() {
  if (running) return;
  const ok = initializeConfig();
  if (!ok) {
    onStatus("配置錯誤，請檢查控制台");
    return;
  }
  onStatus("初始化...");

  lastFaceDetectionState = false;

  // 初始化镜头模式和时间戳
  resetVideoTimestamp();
  setCurrentFacingMode(cameraManager.getCurrentFacingMode());

  syncCanvasSize();

  try {
    await mediaPipeManager.init(outCanvas);
    await cameraManager.startCamera();

    running = true;
    onStatus("檢測中");
    requestAnimationFrame(renderLoop);
  } catch (error) {
    console.error("相機啟動失敗:", error);

    // 根據錯誤類型提供更精確的用戶提示
    let errorMessage = "相機啟動失敗";
    if (error?.name === "NotAllowedError") {
      errorMessage = "相機權限被拒絕，請允許瀏覽器存取相機";
    } else if (error?.name === "NotFoundError") {
      errorMessage = "找不到相機設備";
    } else if (error?.name === "NotReadableError") {
      errorMessage = "相機被其他程式佔用，請關閉其他應用程式後重試";
    } else if (error?.name === "OverconstrainedError") {
      errorMessage = "相機設定不相容，請嘗試重新整理頁面";
    } else if (error?.name === "SecurityError") {
      errorMessage = "安全環境錯誤，請使用 HTTPS 或 localhost";
    }

    onStatus(errorMessage);
    throw error; // 重新拋出錯誤，讓上層 UI 可以處理
  }
}

export function stop() {
  running = false;
  cameraManager.stopCamera();
  if (outCtx && maskCtx && bgCtx) {
    outCtx.clearRect(0, 0, outCanvas.width, outCanvas.height);
    maskCtx.clearRect(0, 0, maskCanvas.width, maskCanvas.height);
    bgCtx.clearRect(0, 0, bgCanvas.width, bgCanvas.height);
  }
  lastFaceDetectionState = false;

  onStats({ faceCount: 0, facesInArea: 0, moonActive: false });
  onStatus("已停止");
}

export function onResize() {
  if (running) syncCanvasSize();
}

