// cameraManager.js - 相機控制管理
// 負責：相機初始化、切換、串流控制

import { CONFIG } from "./config.js";

// DEBUG 模式控制
const DEBUG = false; // 需要除錯時改成 true
function dlog(...args) {
  if (DEBUG) console.log(...args);
}
function dwarn(...args) {
  if (DEBUG) console.warn(...args);
}

// 更可靠的行動裝置偵測（含 iPadOS）
function isMobileLike() {
  const ua = (navigator.userAgent || "").toLowerCase();
  const uaDataMobile = navigator.userAgentData?.mobile === true;
  const touchMac =
    navigator.platform === "MacIntel" && navigator.maxTouchPoints > 1; // iPadOS 假裝 Mac
  const classicMobile = /iphone|ipad|ipod|android/.test(ua);
  return uaDataMobile || touchMac || classicMobile;
}

// 平台判斷
const UA = navigator.userAgent || "";
const IS_MOBILE = isMobileLike();

// 幫桌機挑一顆可用的預設相機（同步暫存 deviceId）
async function pickDesktopDefaultDeviceId() {
  try {
    const devices = await navigator.mediaDevices.enumerateDevices();
    const vids = devices.filter((d) => d.kind === "videoinput");
    // 和 normalizeVideoInputs 一樣的虛擬鏡頭排除規則
    const VIRTUAL_RE =
      /(virtual|obs|ndi|snap\s*camera|manycam|xsplit|v4l2loopback|continuity|連續互通|camo|reincubate|droidcam|ivcam|mmhmm|epocam|splitcam|altercam|webex|teams)/i;
    const real = vids.filter((d) => !VIRTUAL_RE.test(d.label || ""));
    const pick = (arr) => arr[0]?.deviceId || arr[0]?.groupId || null;
    return pick(real.length ? real : vids);
  } catch {}
  return null;
}

export class CameraManager {
  constructor() {
    this.stream = null;
    this.currentFacingMode = CONFIG.CAMERA.DEFAULT_FACING_MODE || "user";
    this.videoEl = null;
    // 每種 facing 各記一組 deviceId
    this.lastDeviceIdByFacing = {
      user: null,
      environment: null,
    };

    // 新增：由外部強制決定是否當作 mobile（使用更可靠的偵測）
    this._isMobile = isMobileLike();

    // hasMultipleCameras 快取（避免頻繁查詢硬體）
    this._hasMultiCache = { at: 0, val: null };

    // 桌機持久化：讀取之前保存的設定
    try {
      const saved = JSON.parse(localStorage.getItem("cm_persist") || "{}");
      if (saved?.desktop?.user)
        this.lastDeviceIdByFacing.user = saved.desktop.user;
      if (saved?.desktop?.environment)
        this.lastDeviceIdByFacing.environment = saved.desktop.environment;
    } catch {}
  }

  // 設定影片元素
  setVideoElement(videoEl) {
    this.videoEl = videoEl;
  }

  // 設定平台模式（由外部強制決定）
  setMobileMode(isMobile) {
    this._isMobile = !!isMobile;
    console.log("📱 CameraManager mobile mode =", this._isMobile);
  }

  // 選擇 constraints（優先用記憶的 deviceId）
  pickConstraints(facing = this.currentFacingMode) {
    // 行動裝置：使用寬鬆 constraints（避免 OverconstrainedError）
    if (this._isMobile) {
      const remembered = this.lastDeviceIdByFacing[facing];
      const video = remembered
        ? { deviceId: { exact: remembered } }
        : // iOS 對 exact 很挑，先用 ideal（或直接 'user' 字串也可）
          { facingMode: { ideal: facing } };

      Object.assign(video, {
        // 不設 min，讓瀏覽器自由協商，避免低規鏡頭 Overconstrained
        width: { ideal: 1280 },
        height: { ideal: 720 },
        // 手機保留 16:9 偏好
        aspectRatio: { ideal: 16 / 9 },
        frameRate: { ideal: CONFIG.CAMERA.FRAME_RATE || 30 },
      });

      return { video, audio: false };
    }

    // 桌機：完全不帶 facingMode，優先 deviceId
    const remembered = this.lastDeviceIdByFacing[facing];
    const video = remembered ? { deviceId: { exact: remembered } } : {};

    Object.assign(video, {
      width: { ideal: 1280 }, // 不設 min，降低約束
      height: { ideal: 720 },
      // aspectRatio 在桌機拿掉，避免驅動不給協商
      frameRate: { ideal: CONFIG.CAMERA.FRAME_RATE || 30, max: 30 },
    });

    return { video, audio: false };
  }

  // 檢查是否接近 16:9 長寬比
  isApprox169(w, h) {
    const ar = w / h;
    return Math.abs(ar - 16 / 9) < 0.02; // 容忍度 2%
  }

  // 標準化長寬比到 16:9
  async normalizeAspect(track) {
    // 手機才嚴格追 16:9；桌機只是「盡量」
    if (!this._isMobile) return;

    const s = track.getSettings?.() || {};
    if (s.width && s.height && this.isApprox169(s.width, s.height)) return;

    try {
      await track.applyConstraints({
        width: { ideal: 1280 },
        height: { ideal: 720 },
        aspectRatio: { ideal: 16 / 9 },
      });
    } catch (e) {
      console.warn("無法調整長寬比:", e);
    }
  }

  // 啟動相機
  async startCamera() {
    // 關閉舊串流
    if (this.stream) {
      try {
        this.stream.getTracks().forEach((t) => t.stop());
      } catch {}
      this.stream = null;
    }

    const facing = this.currentFacingMode;

    // —— 行動裝置：維持原本流程 ——
    if (this._isMobile) {
      try {
        // A. 先用 pickConstraints（記憶 deviceId 或 facingMode）
        const constraints = this.pickConstraints(facing);
        console.log(
          "🎛️ Mobile primary getUserMedia constraints =",
          JSON.stringify(constraints)
        );
        this.stream = await navigator.mediaDevices.getUserMedia(constraints);
      } catch (e) {
        console.warn(
          "Mobile primary constraints failed:",
          e?.name,
          e?.message,
          "constraint:",
          e?.constraint
        );

        // 階梯式 fallback：ideal → exact → 無 facingMode

        // Step 2: 改用 facingMode: { ideal }
        try {
          const constraints = {
            video: {
              facingMode: { ideal: facing },
              width: { ideal: 1280 },
              height: { ideal: 720 },
              aspectRatio: { ideal: 16 / 9 },
              frameRate: { ideal: CONFIG.CAMERA.FRAME_RATE || 30 },
            },
            audio: false,
          };
          console.log(
            "🎛️ Mobile fallback #2 (ideal facingMode) constraints =",
            JSON.stringify(constraints)
          );
          this.stream = await navigator.mediaDevices.getUserMedia(constraints);
        } catch (eIdeal) {
          console.warn(
            "Mobile fallback #2 (ideal facingMode) failed:",
            eIdeal?.name,
            eIdeal?.message
          );

          // Step 3: 再試 exact（少數裝置反而吃 exact）
          try {
            this.lastDeviceIdByFacing[facing] = null; // 清空記憶，嘗試重新選擇
            const constraints = {
              video: {
                facingMode: { exact: facing },
                width: { ideal: 1280 },
                height: { ideal: 720 },
                aspectRatio: { ideal: 16 / 9 },
                frameRate: { ideal: CONFIG.CAMERA.FRAME_RATE || 30 },
              },
              audio: false,
            };
            console.log(
              "🎛️ Mobile fallback #3 (exact facingMode) constraints =",
              JSON.stringify(constraints)
            );
            this.stream = await navigator.mediaDevices.getUserMedia(
              constraints
            );
          } catch (eExact) {
            console.warn(
              "Mobile fallback #3 (exact facingMode) failed:",
              eExact?.name,
              eExact?.message
            );

            // Step 4: 最寬鬆，完全不帶 facingMode
            try {
              const constraints = {
                video: {
                  width: { ideal: 1280 },
                  height: { ideal: 720 },
                  frameRate: { ideal: CONFIG.CAMERA.FRAME_RATE || 30 },
                },
                audio: false,
              };
              console.log(
                "🎛️ Mobile fallback #4 (no facingMode) constraints =",
                JSON.stringify(constraints)
              );
              this.stream = await navigator.mediaDevices.getUserMedia(
                constraints
              );
            } catch (eNoFacing) {
              console.warn(
                "Mobile fallback #4 (no facingMode) failed:",
                eNoFacing?.name,
                eNoFacing?.message
              );

              // Step 5: 最後手段 - 暖機 + 最寬鬆重試
              try {
                console.log("🔥 Mobile final attempt: warm-up + retry");
                const warm = await navigator.mediaDevices.getUserMedia({
                  video: true,
                  audio: false,
                });
                warm.getTracks().forEach((t) => t.stop());
                const constraints = {
                  video: { width: { ideal: 1280 }, height: { ideal: 720 } },
                  audio: false,
                };
                this.stream = await navigator.mediaDevices.getUserMedia(
                  constraints
                );
              } catch (eWarmup) {
                console.error("❌ All mobile fallback attempts failed");
                throw e; // 拋出最原始的錯誤
              }
            }
          }
        }
      }

      const track = this.stream.getVideoTracks()[0];
      const s = track.getSettings?.() || {};
      if (s.deviceId) this.lastDeviceIdByFacing[facing] = s.deviceId;

      // 重置 zoom
      try {
        const caps = track.getCapabilities?.();
        if (caps?.zoom !== undefined)
          await track.applyConstraints({ advanced: [{ zoom: 1.0 }] });
      } catch (e) {
        console.warn("無法設定 zoom:", e);
      }

      await this.normalizeAspect(track);
    }
    // —— 桌機：新的穩健路線 ——
    else {
      let lastErr = null;

      await this._desktopWarmUpPermission(); // ★ 新增：桌機暖機

      // Step 0：優先用本地持久化（同一顆 + 同一解析度）
      const persisted = this._readDesktopPersist();
      if (persisted?.[facing]) {
        this.lastDeviceIdByFacing[facing] = persisted[facing];
        try {
          const constraints = {
            video: {
              deviceId: { exact: this.lastDeviceIdByFacing[facing] },
              width: persisted.width
                ? { exact: persisted.width }
                : { ideal: 1280 },
              height: persisted.height
                ? { exact: persisted.height }
                : { ideal: 720 },
              // 先不帶 frameRate 上限，避免驅動打架
              frameRate: { ideal: CONFIG.CAMERA.FRAME_RATE || 30 },
              resizeMode: "none",
            },
            audio: false,
          };
          console.log(
            "🎛️ Desktop P0 (persisted exact) =",
            JSON.stringify(constraints)
          );
          this.stream = await navigator.mediaDevices.getUserMedia(constraints);
        } catch (eP0) {
          console.warn(
            "Desktop P0 (persisted) failed:",
            eP0?.name,
            eP0?.message
          );
        }
      }

      // P-1: 若沒有持久化設定，先用嚴格 1280x720 + 禁裁切做初探
      if (!this.stream && !persisted?.[facing]) {
        try {
          const constraints = {
            video: {
              width: { exact: 1280 },
              height: { exact: 720 },
              // 禁裁切：若不支援，瀏覽器會忽略，不會 throw
              resizeMode: "none",
            },
            audio: false,
          };
          console.log(
            "🎛️ Desktop P-1 (prefer 1280x720 exact, no-crop)",
            JSON.stringify(constraints)
          );
          this.stream = await navigator.mediaDevices.getUserMedia(constraints);
        } catch (eP1) {
          console.warn("Desktop P-1 failed:", eP1?.name, eP1?.message);
        }
      }

      // 若還沒有 stream，才進入 T1/T2/T3 的階梯
      if (!this.stream && !this.lastDeviceIdByFacing[facing]) {
        this.lastDeviceIdByFacing[facing] = await pickDesktopDefaultDeviceId();
      }

      const remembered = this.lastDeviceIdByFacing[facing];

      // T1: deviceId(ideal) + 寬鬆尺寸 + 無 aspectRatio
      try {
        const video = remembered ? { deviceId: { ideal: remembered } } : {};
        Object.assign(video, {
          width: { ideal: 1280, min: 320 }, // 放寬，避免 Overconstrained
          height: { ideal: 720, min: 240 },
          // 先拿掉 frameRate 的 max；有些內建鏡頭卡在 25/60
          frameRate: { ideal: CONFIG.CAMERA.FRAME_RATE || 30 },
        });
        const constraints = { video, audio: false };
        console.log(
          "🎛️ Desktop T1 (ideal) getUserMedia constraints =",
          JSON.stringify(constraints)
        );
        this.stream = await navigator.mediaDevices.getUserMedia(constraints);
      } catch (e1) {
        lastErr = e1;
        console.warn("Desktop try#1 (ideal) failed:", e1?.name, e1?.message);
      }

      // T2: 嚴格 exact（若 T1 不通）
      if (!this.stream && remembered) {
        try {
          const constraints = {
            video: { deviceId: { exact: remembered } },
            audio: false,
          };
          console.log(
            "🎛️ Desktop T2 (exact) getUserMedia constraints =",
            JSON.stringify(constraints)
          );
          this.stream = await navigator.mediaDevices.getUserMedia(constraints);
        } catch (e2) {
          lastErr = e2;
          console.warn("Desktop try#2 (exact) failed:", e2?.name, e2?.message);
        }
      }

      // T3: 最寬鬆
      if (!this.stream) {
        try {
          const constraints = { video: true, audio: false };
          console.log(
            "🎛️ Desktop T3 (true) getUserMedia constraints =",
            JSON.stringify(constraints)
          );
          this.stream = await navigator.mediaDevices.getUserMedia(constraints);
        } catch (e3) {
          lastErr = e3;
          console.error("Desktop try#3 (true) failed:", e3?.name, e3?.message);
        }
      }

      // Quick-swap: 如果看起來是裝置佔用，嘗試換下一顆
      if (
        !this.stream &&
        (lastErr?.name === "NotReadableError" || lastErr?.name === "AbortError")
      ) {
        try {
          const devices = await navigator.mediaDevices.enumerateDevices();
          const cams = devices.filter((d) => d.kind === "videoinput");
          const alternative = cams.find(
            (d) => d.deviceId !== this.lastDeviceIdByFacing[facing]
          );
          if (alternative?.deviceId) {
            console.warn(
              "🎯 Quick-swap to another camera:",
              alternative.label || alternative.deviceId
            );
            this.lastDeviceIdByFacing[facing] = alternative.deviceId;
            const constraints = {
              video: { deviceId: { exact: alternative.deviceId } },
              audio: false,
            };
            console.log(
              "🎛️ Desktop Quick-swap getUserMedia constraints =",
              JSON.stringify(constraints)
            );
            this.stream = await navigator.mediaDevices.getUserMedia(
              constraints
            );
          }
        } catch (e4) {
          console.warn("Quick-swap failed:", e4?.name, e4?.message);
        }
      }

      // 如果還是失敗，拋出錯誤
      if (!this.stream) {
        throw lastErr || new Error("所有桌機相機啟動嘗試都失敗");
      }

      // 記憶實際成功的 deviceId（之後切換/重啟更穩）
      const track = this.stream.getVideoTracks()[0];
      const s = track.getSettings?.() || {};
      const caps = track.getCapabilities?.() || {};
      if (s.deviceId) this.lastDeviceIdByFacing[facing] = s.deviceId;

      // 合格檢查函數
      const approx169 = (w, h) => Math.abs(w / h - 16 / 9) < 0.02;
      const goodSize = (w, h) => w >= 960 && h >= 540; // 不要鎖 640x480

      // 如果第一次談到的結果不夠好 → 立刻重談到理想解析度
      if (!approx169(s.width, s.height) || !goodSize(s.width, s.height)) {
        console.warn("第一次協商結果不理想，嘗試 re-negotiate:", {
          width: s.width,
          height: s.height,
        });
        try {
          // 先嘗試 1280x720 + 禁裁切
          await track.applyConstraints({
            width: { ideal: 1280 },
            height: { ideal: 720 },
            resizeMode: "none",
          });
          console.log("✅ Re-negotiate 到 1280x720 成功");
        } catch (eA) {
          console.warn("re-negotiate 到 1280×720 失敗:", eA?.name);
          try {
            // 次佳 960×540
            await track.applyConstraints({
              width: { ideal: 960 },
              height: { ideal: 540 },
              resizeMode: "none",
            });
            console.log("✅ Re-negotiate 到 960x540 成功");
          } catch (eB) {
            console.warn("re-negotiate 到 960×540 失敗:", eB?.name);
            // 讓它維持原本 s.width/s.height，下面仍會做禁裁切/歸零
          }
        }
      }

      // 重新讀一次最終設定
      const s2 = track.getSettings?.() || { width: s.width, height: s.height };

      // 🔒 桌機：強化為「禁止裁切 + 重置 zoom/pan/tilt + 鎖解析度」
      try {
        const adv = [];
        if (caps.zoom !== undefined) adv.push({ zoom: 1.0 });
        if (caps.pan !== undefined) adv.push({ pan: 0 });
        if (caps.tilt !== undefined) adv.push({ tilt: 0 });

        await track.applyConstraints({
          width: { exact: s2.width || 1280 },
          height: { exact: s2.height || 720 },
          ...(caps.resizeMode && caps.resizeMode.length
            ? { resizeMode: "none" }
            : {}),
          ...(adv.length ? { advanced: adv } : {}),
        });
        console.log("🔒 桌機鎖定成功:", {
          width: s2.width || 1280,
          height: s2.height || 720,
          resizeMode: "none",
        });
      } catch (eC) {
        console.warn("lock exact/resizeMode/zoom reset 失敗:", eC?.name);
      }

      // ✅ 只保存合格的設定到 localStorage
      if (approx169(s2.width, s2.height) && goodSize(s2.width, s2.height)) {
        this._saveDesktopPersist(
          facing,
          this.lastDeviceIdByFacing[facing],
          s2.width || 1280,
          s2.height || 720
        );
        console.log("✅ 保存合格設定:", { width: s2.width, height: s2.height });
      } else {
        console.warn("❌ 跳過持久化：第一次協商結果不夠理想", {
          width: s2.width,
          height: s2.height,
        });
      }
    }

    // 綁定到 <video>
    this.videoEl.srcObject = this.stream;
    this.videoEl.setAttribute("playsinline", "");
    this.videoEl.muted = true;
    this.videoEl.autoplay = true;

    await new Promise((resolve) => {
      if (
        this.videoEl.readyState >= 1 &&
        this.videoEl.videoWidth &&
        this.videoEl.videoHeight
      )
        return resolve();
      this.videoEl.onloadedmetadata = () => resolve();
      setTimeout(resolve, 1500);
    });

    console.log("📷 相機啟動完成:", {
      platform: this._isMobile ? "mobile" : "desktop",
      facing,
      deviceId: this.lastDeviceIdByFacing[facing],
      resolution: `${this.videoEl.videoWidth}x${this.videoEl.videoHeight}`,
      aspectRatio: (this.videoEl.videoWidth / this.videoEl.videoHeight).toFixed(
        3
      ),
    });

    try {
      await this.videoEl.play();
    } catch {}
  }

  // 停止相機
  stopCamera() {
    try {
      if (this.stream) this.stream.getTracks().forEach((t) => t.stop());
    } catch {}
    this.stream = null;
  }

  // 切換前後鏡頭
  async switchCamera() {
    // 只改變 facing，各自記各自的 deviceId
    this.currentFacingMode =
      this.currentFacingMode === "user" ? "environment" : "user";
    console.log("🔄 切換鏡頭到:", this.currentFacingMode);
    await this.startCamera();
  }

  // 取得當前鏡頭模式
  getCurrentFacingMode() {
    return this.currentFacingMode;
  }

  // 重置特定 facing 的 deviceId 記憶（用於 fallback 或手動重置）
  resetDeviceId(facing = null) {
    if (facing) {
      this.lastDeviceIdByFacing[facing] = null;
      console.log(`🔄 重置 ${facing} deviceId 記憶`);
    } else {
      // 重置所有 facing 的記憶
      this.lastDeviceIdByFacing = { user: null, environment: null };
      console.log("🔄 重置所有 deviceId 記憶");
    }
  }

  // 取得串流
  getStream() {
    return this.stream;
  }

  // 檢測是否有多個攝像頭（前後鏡頭）— 加上快取
  async hasMultipleCameras() {
    const now = Date.now();
    // 快取 10 秒
    if (
      this._hasMultiCache.val != null &&
      now - this._hasMultiCache.at < 10_000
    ) {
      return this._hasMultiCache.val;
    }
    try {
      const devices = await navigator.mediaDevices.enumerateDevices();
      const videoInputs = devices.filter(
        (device) => device.kind === "videoinput"
      );
      const val = videoInputs.length > 1;
      this._hasMultiCache = { at: now, val };
      return val;
    } catch (error) {
      dwarn("無法檢測攝像頭設備:", error);
      this._hasMultiCache = { at: now, val: false };
      return false;
    }
  }

  // 桌機暖機授權（解鎖 getUserMedia 權限）
  async _desktopWarmUpPermission() {
    // 僅在沒有任何 stream 且尚未記憶 deviceId 時暖機授權
    if (this.stream) return;
    try {
      const warmConstraints = { video: true, audio: false };
      console.log(
        "🎛️ Desktop warm-up getUserMedia constraints =",
        JSON.stringify(warmConstraints)
      );
      const warm = await navigator.mediaDevices.getUserMedia(warmConstraints);
      warm.getTracks().forEach((t) => t.stop());
      console.log("🟢 Desktop warm-up permission ok");
    } catch (e) {
      console.warn(
        "🟡 Desktop warm-up failed (still proceed):",
        e?.name,
        e?.message
      );
      // 不要丟錯，繼續後續流程；有些環境雖失敗仍可直接協商成功
    }
  }

  // 桌機持久化：保存成功的 deviceId 和解析度
  _saveDesktopPersist(facing, deviceId, width, height) {
    try {
      const saved = JSON.parse(localStorage.getItem("cm_persist") || "{}");
      saved.desktop = saved.desktop || {};
      saved.desktop[facing] = deviceId;
      saved.desktop.width = width;
      saved.desktop.height = height;
      localStorage.setItem("cm_persist", JSON.stringify(saved));
      console.log(
        `💾 桌機持久化保存: ${facing} = ${deviceId}, ${width}x${height}`
      );
    } catch (e) {
      console.warn("桌機持久化保存失敗:", e);
    }
  }

  // 桌機持久化：讀取保存的設定
  _readDesktopPersist() {
    try {
      return (
        JSON.parse(localStorage.getItem("cm_persist") || "{}")?.desktop || null
      );
    } catch (e) {
      console.warn("桌機持久化讀取失敗:", e);
      return null;
    }
  }

  // Debug 功能：重置持久化設定
  resetDesktopPersist() {
    try {
      localStorage.removeItem("cm_persist");
      this.lastDeviceIdByFacing = { user: null, environment: null };
      console.log("🔄 桌機持久化設定已重置");
    } catch (e) {
      console.warn("重置桌機持久化失敗:", e);
    }
  }
}

// Debug 全域函數：一鍵重置持久化設定
if (typeof window !== "undefined") {
  window.__cm_reset = () => {
    try {
      localStorage.removeItem("cm_persist");
      console.log("🔄 桌機持久化設定已重置 (全域)");
    } catch (e) {
      console.warn("全域重置失敗:", e);
    }
  };
}
